if (renameBtn) {
  renameBtn.addEventListener('click', () => {
    const from = renameFromInput ? renameFromInput.value.trim() : '';
    const to = renameToInput ? renameToInput.value.trim() : '';
    if (!from || !to || from === to) return;
    if (transactions.some((t) => t.category === from)) {
      transactions = transactions.map((t) => (t.category === from ? { ...t, category: to } : t));
      history.push(transactions);
      saveTransactions(transactions);
    }
    budgets = budgets.map((b) => (b.category === from ? { ...b, category: to } : b));
    saveBudgets(budgets);
    renderAll();
  });
}

